solution:
echo -e "function toCsv(rows) {
  const keys = Object.keys(rows[0] || {})
  const lines = rows.map((row) => keys.map((key) => row[key]).join(','))
  return [keys.join(','), ...lines].join('\n')
}

module.exports = { toCsv }" > src/export/csv.js

